// spec: .qa/e2e/specs/prayer-mode.md
// seed: tests/seed.user1.spec.ts
import { test, expect, Page, Locator } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/user1.json') });

const TOTAL = 57;

async function counterText(page: Page) {
  return ((await page.getByText(/\d+ מתוך \d+/).first().innerText()).match(/\d+ מתוך \d+/) ?? [''])[0];
}

async function goToFirst(page: Page) {
  const prev = page.getByText('קודם', { exact: true });
  for (let i = 0; i < TOTAL + 5; i++) {
    if ((await counterText(page)) === `1 מתוך ${TOTAL}`) break;
    await prev.click();
  }
  await expect(page.getByText(`1 מתוך ${TOTAL}`).first()).toBeVisible();
}

async function style(radio: Locator) {
  return radio.evaluate((el) => ({
    bg: getComputedStyle(el).backgroundColor,
    font: getComputedStyle((el.querySelector('*') as Element) ?? el).fontFamily,
  }));
}

async function expectSelected(selected: Locator, other: Locator) {
  await expect(selected).toHaveAttribute('aria-checked', 'true');
  await expect(other).toHaveAttribute('aria-checked', 'false');
  const s = await style(selected);
  const o = await style(other);
  expect(s.bg).toBe('rgb(219, 171, 100)');
  expect(s.font).toContain('Discovery_Fs-Bold');
  expect(o.font).toContain('Discovery_Fs-Regular');
  expect(o.bg).not.toBe('rgb(219, 171, 100)');
}

test.describe('Режим молитвы «יחיד / מניין»', () => {
  test('PM-01 Переключатель «יחיד/מניין» вверху, по умолчанию «יחיד», выбранный отмечен не только цветом #6a86f7e7 @prod-safe', async ({ page }) => {
    // Чистый localStorage для режима молитвы (проверка значения по умолчанию)
    await page.addInitScript(() => {
      try { localStorage.removeItem('prayer-progress'); } catch {}
    });

    // 1. Открыть `/prayer/shacharit_sfarad`.
    await page.goto('/prayer/shacharit_sfarad');
    await expect(page.getByText(/\d+ מתוך \d+/).first()).toBeVisible();

    // 2. Нажимать «קודם», пока счётчик не покажет «1 מתוך 57».
    await goToFirst(page);

    // 3. Посмотреть верх экрана под счётчиком: найти radio «יחיד» и «מניין».
    const yachid = page.getByRole('radio', { name: 'יחיד' });
    const minyan = page.getByRole('radio', { name: 'מניין' });
    await expect(yachid).toBeVisible();
    await expect(minyan).toBeVisible();
    // Два варианта вверху, под счётчиком
    const counterBox = await page.getByText('1 מתוך 57').first().boundingBox();
    const yBox = await yachid.boundingBox();
    const mBox = await minyan.boundingBox();
    expect(yBox!.y).toBeGreaterThanOrEqual(counterBox!.y + counterBox!.height);
    expect(mBox!.y).toBeGreaterThanOrEqual(counterBox!.y + counterBox!.height);
    expect(yBox!.y).toBeLessThan(300);
    // По умолчанию «יחיד»: aria-checked, золотой фон, жирный шрифт
    await expectSelected(yachid, minyan);

    // 4. Нажать «מניין».
    await minyan.click();
    await expectSelected(minyan, yachid);

    // 5. Нажать «יחיד».
    await yachid.click();
    await expectSelected(yachid, minyan);
  });
});
